#include <stdio.h>

int main() {
    int note = 14;

    if (note >= 10) {
        printf("Admis\n");
    } else if (note >= 8) {
        printf("Rattrapage\n");
    } else {
        printf("Refusé\n");
    }

    // Switch
    int jour = 3;
    switch (jour) {
        case 1: printf("Lundi\n"); break;
        case 2: printf("Mardi\n"); break;
        case 3: printf("Mercredi\n"); break;
        default: printf("Autre jour\n");
    }
    return 0;
}
